import { test, expect } from '@playwright/test';

test.describe('Responsive Data Tables - Vertical Stacking on Small Screens', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data-tables');
  });

  test('should stack data tables vertically on small screens', async ({ page }) => {
    // Setup: Load the page with multiple data tables
    await page.route('**/api/data-tables/list', async (route) => {
      await route.continue();
    });

    // Verify initial state: Data tables should be horizontal
    const table1 = page.getByRole('table');
    await expect(table1).toBeVisible();
    const table2 = page.getByRole('table');
    await expect(table2).toBeVisible();
    const table3 = page.getByRole('table');
    await expect(table3).toBeVisible();

    // Verify table headers are visible
    const table1Header = page.getByRole('heading', { name: /table 1/i });
    await expect(table1Header).toBeVisible();
    const table2Header = page.getByRole('heading', { name: /table 2/i });
    await expect(table2Header).toBeVisible();
    const table3Header = page.getByRole('heading', { name: /table 3/i });
    await expect(table3Header).toBeVisible();

    // Verify table rows are visible
    const table1Row = page.getByRole('row', { name: /row 1/i });
    await expect(table1Row).toBeVisible();
    const table2Row = page.getByRole('row', { name: /row 2/i });
    await expect(table2Row).toBeVisible();
    const table3Row = page.getByRole('row', { name: /row 3/i });
    await expect(table3Row).toBeVisible();

    // Set viewport width to trigger responsive behavior
    await page.setViewportSize({ width: 320, height: 480 });

    // Verify tables stack vertically
    const table1Stacked = page.getByRole('table');
    await expect(table1Stacked).toHaveClass(/stacked/i);
    const table2Stacked = page.getByRole('table');
    await expect(table2Stacked).toHaveClass(/stacked/i);
    const table3Stacked = page.getByRole('table');
    await expect(table3Stacked).toHaveClass(/stacked/i);

    // Verify table headers are still visible
    await expect(table1Header).toBeVisible();
    await expect(table2Header).toBeVisible();
    await expect(table3Header).toBeVisible();

    // Verify table rows are still visible
    await expect(table1Row).toBeVisible();
    await expect(table2Row).toBeVisible();
    await expect(table3Row).toBeVisible();

    // Verify table content is accessible
    const table1Cell = page.getByRole('cell', { name: /cell 1/i });
    await expect(table1Cell).toBeVisible();
    const table2Cell = page.getByRole('cell', { name: /cell 2/i });
    await expect(table2Cell).toBeVisible();
    const table3Cell = page.getByRole('cell', { name: /cell 3/i });
    await expect(table3Cell).toBeVisible();

